from typing import List, Dict, Tuple

def quick_buck(lst: List[Tuple[str, int]]) -> Dict[str, int]:
    """Calculate the total sum of a list of tuples representing transactions.

    Args:
        lst: A list of tuples, where each tuple contains a transaction description and a value.

    Returns:
        A dictionary where the keys are the transaction descriptions and the values are the sums of the transactions.

    Example:
        >>> quick_buck([("apple", 10), ("banana", 20), ("apple", 5)])
        {'apple': 15, 'banana': 20}
    """
    result = {}
    for item, amount in lst:
        if item in result:
            result[item] += amount
        else:
            result[item] = amount
    return result

